import{_ as i,a0 as r,w as l,s as u,I as s,x as t,a1 as o,A as a,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"如何在 Linux 桌面添加用户 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 桌面添加用户 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 桌面添加用户 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 桌面添加用户 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191107 How to add a user to your Linux desktop","title":"如何在 Linux 桌面添加用户","tag":"201911","desc":""},"relativePath":"201911/20191107 How to add a user to your Linux desktop.md","filePath":"[post].md"}'),p={name:"201911/20191107 How to add a user to your Linux desktop.md"};function m(f,e,g,x,L,T){const n=r("Link");return l(),u("div",null,[e[20]||(e[20]=s("h1",{id:"如何在-linux-桌面添加用户",tabindex:"-1"},[t("如何在 Linux 桌面添加用户 "),s("a",{class:"header-anchor",href:"#如何在-linux-桌面添加用户","aria-label":"Permalink to “如何在 Linux 桌面添加用户”"},"​")],-1)),e[21]||(e[21]=s("blockquote",null,[s("p",null,"无论是在安装过程中还是在桌面中，通过图形界面管理用户都非常容易。")],-1)),e[22]||(e[22]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/team_global_people_gis_location.png?itok=Rl2IKo12",alt:"Team of people around the world",title:"Team of people around the world"})],-1)),e[23]||(e[23]=s("p",null,"添加用户是你在一个新系统上要做的第一件事。而且，你通常需要在计算机的整个生命周期中管理用户。",-1)),s("p",null,[e[1]||(e[1]=t("我的关于 ",-1)),o(n,{href:"https://opensource.com/article/19/10/linux-useradd-command"},{default:a(()=>[...e[0]||(e[0]=[t("useradd 命令",-1)])]),_:1}),e[2]||(e[2]=t("文章提供了更深入的对 Linux 的用户管理的了解。",-1)),e[3]||(e[3]=s("code",null,"useradd",-1)),e[4]||(e[4]=t(" 是一个命令行工具，但是你也可以在 Linux 上以图形方式管理用户。这就是本文的主题。",-1))]),e[24]||(e[24]=d('<h3 id="在-linux-安装过程中添加用户" tabindex="-1">在 Linux 安装过程中添加用户 <a class="header-anchor" href="#在-linux-安装过程中添加用户" aria-label="Permalink to “在 Linux 安装过程中添加用户”">​</a></h3><p>大多数 Linux 发行版都提供了在安装过程中创建用户的步骤。例如，Fedora 30 安装程序 Anaconda 创建标准的 <code>root</code> 用户和另一个本地用户帐户。在安装过程中进入“配置”页面时，单击“用户设置”下的“用户创建”。</p><p><img src="https://opensource.com/sites/default/files/uploads/screenshot_fedora30_anaconda2.png" alt="Fedora Anaconda Installer - Add a user" title="Fedora Anaconda Installer - Add a user"></p><p>在用户创建页面上，输入用户的详细信息：全名、用户名和密码。你还可以选择是否使用户成为管理员。</p><p><img src="https://opensource.com/sites/default/files/uploads/screenshot_fedora30_anaconda3.png" alt="Create a user during installation" title="Create a user during installation"></p><p>点击“高级”按钮打开“高级用户配置”页面。如果需要除默认设置以外的其他设置，那么可以在此处指定主目录的路径以及用户和组 ID。你也可以输入用户所属的其他组。</p><p><img src="https://opensource.com/sites/default/files/uploads/screenshot_fedora30_anaconda4.png" alt="Advanced user configuration" title="Advanced user configuration"></p><h3 id="在-linux-桌面上添加用户" tabindex="-1">在 Linux 桌面上添加用户 <a class="header-anchor" href="#在-linux-桌面上添加用户" aria-label="Permalink to “在 Linux 桌面上添加用户”">​</a></h3><h4 id="gnome" tabindex="-1">GNOME <a class="header-anchor" href="#gnome" aria-label="Permalink to “GNOME”">​</a></h4><p>许多 Linux 发行版都使用 GNOME 桌面。以下截图来自 Red Hat Enterprise Linux 8.0，但是在其他发行版（如 Fedora、Ubuntu 或 Debian）中，该过程相似。</p><p>首先打开“设置”。然后打开“详细”，选择“用户”，单击“解锁”，然后输入密码（除非你已经以 root 用户登录）。这样将用“添加用户”按钮代替“解锁”按钮。</p><p><img src="https://opensource.com/sites/default/files/uploads/gnome_settings_user_unlock.png" alt="GNOME user settings" title="GNOME user settings"></p><p>现在，你可以通过单击“添加用户”，然后选择“帐户类型”然后输入“用户名”和“密码”来添加用户。</p><p>在下面的截图中，已经输入了用户名，设置保留为默认设置。我不必输入“用户名”，因为它是在我在“全名”字段中输入时自动创建的。如果你不喜欢自动补全，你仍然可以对其进行修改。</p><p><img src="https://opensource.com/sites/default/files/uploads/gnome_settings_adding_user.png" alt="GNOME settings - add user" title="GNOME settings - add user"></p><p>这将为名为 Sonny 的用户创建一个标准帐户。Sonny 首次登录时需要提供密码。</p><p>接下来，将显示用户。在此页面可以选择每个用户进行自定义或者删除。例如，你可能想选择一个头像或设置默认语言。</p><p><img src="https://opensource.com/sites/default/files/uploads/gnome_settings_user_new.png" alt="GNOME new user" title="GNOME new user"></p><h4 id="kde" tabindex="-1">KDE <a class="header-anchor" href="#kde" aria-label="Permalink to “KDE”">​</a></h4><p>KDE 是另一个流行的 Linux 桌面环境。下面是 Fedora 30 上 KDE Plasma 的截图。你可以看到，在 KDE 中添加用户与在 GNOME 中添加用户非常相似。</p><p><img src="https://opensource.com/sites/default/files/uploads/kde_settings_adding_user.png" alt="KDE settings - add user" title="KDE settings - add user"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>除 GNOME 和 KDE 外，其他桌面环境和窗口管理器也有图形用户管理工具。无论是在安装时还是安装后，在 Linux 中以图形方式添加用户都是快速简便的。</p><hr>',24)),s("p",null,[e[6]||(e[6]=t("via: ",-1)),o(n,{href:"https://opensource.com/article/19/11/add-user-gui-linux"},{default:a(()=>[...e[5]||(e[5]=[t("https://opensource.com/article/19/11/add-user-gui-linux",-1)])]),_:1})]),s("p",null,[e[11]||(e[11]=t("作者：",-1)),o(n,{href:"https://opensource.com/users/alanfdoss"},{default:a(()=>[...e[7]||(e[7]=[t("Alan Formy-Duval",-1)])]),_:1}),e[12]||(e[12]=t(" 选题：",-1)),o(n,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[8]||(e[8]=[t("lujun9972",-1)])]),_:1}),e[13]||(e[13]=t(" 译者：",-1)),o(n,{href:"https://github.com/geekpi"},{default:a(()=>[...e[9]||(e[9]=[t("geekpi",-1)])]),_:1}),e[14]||(e[14]=t(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[10]||(e[10]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[17]||(e[17]=t("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[15]||(e[15]=[t("LCTT",-1)])]),_:1}),e[18]||(e[18]=t(" 原创编译，",-1)),o(n,{href:"https://linux.cn/"},{default:a(()=>[...e[16]||(e[16]=[t("Linux中国",-1)])]),_:1}),e[19]||(e[19]=t(" 荣誉推出",-1))])])}const h=i(p,[["render",m]]);export{b as __pageData,h as default};
